const residents=[
{name:'Edgar',years:'1842 — 1901',epitaph:'He was dying to see her again.',letter:'I saved you the last dance.\nI seem to have misplaced my feet, but the offer still stands.'},
{name:'Florence',years:'1850 — 1923',epitaph:'Still holding a grudge. And a rose.',letter:'You brought me flowers every Friday.\nNow they grow above me. I like to think you arranged that.'},
{name:'Arthur',years:'1867 — 1932',epitaph:'Late to everything. Finally early.',letter:'If I had another lifetime, I would find you sooner.\nAnd I would learn to cook something besides toast.'},
{name:'Mabel',years:'1871 — 1940',epitaph:'Took her secrets underground.',letter:'The secret ingredient was never cinnamon.\nIt was making two cups, even when I only wanted one.'},
{name:'Oscar',years:'1888 — 1949',epitaph:'A hopeless romantic. Mostly hopeless.',letter:'They said love would be the death of me.\nActually, it was the stairs. But you were worth every climb.'},
{name:'Rose',years:'1893 — 1964',epitaph:'Loved fiercely. Haunts politely.',letter:'When the garden goes quiet, listen carefully.\nThat is me, still telling you about my day.'}
];
const key='love-you-to-death-v1';let found=[];try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))found=[...new Set(saved.filter(i=>Number.isInteger(i)&&i>=0&&i<6))]}catch{}
let active=0,depth=0;const $=id=>document.getElementById(id);function save(){try{localStorage.setItem(key,JSON.stringify(found))}catch{}}
function showLetter(i){$('letterTitle').textContent=i===6?'For my favorite person.':`A letter from ${residents[i].name}`;$('letterText').textContent=i===6?'I would dig through a whole cemetery to find you.\nLuckily, I only had to make you this game.\n\nLove you to death. ♡':residents[i].letter;$('letterDialog').showModal()}
function render(){$('count').textContent=`${found.length} / 6`;$('graves').replaceChildren();residents.forEach((r,i)=>{const b=document.createElement('button');b.className='grave'+(found.includes(i)?' done':'');b.innerHTML=`<span class="cross">${found.includes(i)?'♡':'✝'}</span><strong>${r.name}</strong><small>${r.years}</small>`;b.setAttribute('aria-label',`${r.name}: ${found.includes(i)?'read recovered letter':'excavate grave'}`);b.onclick=()=>openGrave(i);$('graves').append(b)});$('letters').replaceChildren();if(!found.length){$('letters').innerHTML='<p class="empty">Six lives. Six letters. Your first discovery awaits.</p>'}found.forEach(i=>{const b=document.createElement('button');b.textContent=`✉ ${residents[i].name}`;b.onclick=()=>showLetter(i);$('letters').append(b)});if(found.length===6){const b=document.createElement('button');b.textContent='♡ Your final letter';b.className='primary';b.onclick=()=>showLetter(6);$('letters').append(b)}}
function openGrave(i){if(found.includes(i)){showLetter(i);return}active=i;depth=0;$('plot').textContent=`PLOT 0${i+1} · UNFINISHED BUSINESS`;$('resident').textContent=residents[i].name;$('epitaph').textContent=residents[i].epitaph;$('body').textContent='⚒';$('digLabel').textContent='Tap to dig · 5 layers of soil';$('depth').value=0;$('discovery').textContent='There’s something down there. Probably someone.';$('collect').hidden=true;$('soil').disabled=false;$('digDialog').showModal()}
$('soil').onclick=()=>{depth++;$('depth').value=depth;$('digLabel').textContent=`${depth} / 5 layers cleared`;$('discovery').textContent=['','The grass gives way.','A root, a worm, a very bad feeling.','The corner of an old coffin appears.','One more scoop. Someone is waiting.','A skeleton clutches a letter. This was worth getting dirty.'][depth];if(depth===5){$('body').textContent='💀 🦴 ✉';$('soil').disabled=true;$('collect').hidden=false;$('collect').focus()}};
$('collect').onclick=()=>{if(!found.includes(active))found.push(active);save();render();$('digDialog').close();showLetter(found.length===6?6:active)};$('close').onclick=()=>$('digDialog').close();$('closeLetter').onclick=()=>$('letterDialog').close();$('reset').onclick=()=>{if(confirm('Start a fresh night? This clears all recovered letters.')){found=[];save();render()}};render();
